/// A cache for storage slots of a single account.
///
/// This caches storage values keyed by their [`StorageKey`], bounded to a configurable maximum
/// number of storage slots.
#[derive(Debug)]
pub(crate) struct AccountStorageCache {
    /// The underlying cache of storage slots.
    cache: Cache<StorageKey, StorageValue>,
}

impl AccountStorageCache {
    /// Creates a new [`AccountStorageCache`] that can hold up to `max_slots` storage slots.
    pub(crate) fn new(max_slots: u64) -> Self {
        Self { cache: CacheBuilder::new(max_slots).build_with_hasher(DefaultHashBuilder::default()) }
    }

    /// Returns the current number of cached storage slots.
    pub(crate) fn len(&self) -> usize {
        self.cache.entry_count() as usize
    }
